PTX_SOURCE = r"""
.version 7.0
.target sm_80
.address_size 64

.visible .entry hinge_mean_kernel(
    .param .u64 pred_ptr,
    .param .u64 targ_ptr,
    .param .u64 out_ptr,
    .param .u32 N
)
{
    // -------------------------------------------------
    // Load kernel arguments
    // -------------------------------------------------
    .reg .u64 %pred, %targ, %out;
    .reg .u32 %N;
    ld.param.u64 %pred, [pred_ptr];
    ld.param.u64 %targ, [targ_ptr];
    ld.param.u64 %out,  [out_ptr];
    ld.param.u32 %N,    [N];

    // -------------------------------------------------
    // Thread / block identifiers
    // -------------------------------------------------
    .reg .u32 %tid, %bdim, %gridDim;
    mov.u32 %tid,   %tid.x;
    mov.u32 %bdim,  %ctaid.x;        // not used, keep for clarity
    mov.u32 %bdim,  %ntid.x;        // blockDim.x
    mov.u32 %gridDim, %nctaid.x;    // gridDim.x (expected 1)

    // -------------------------------------------------
    // Shared memory for block reduction (max 1024 threads)
    // -------------------------------------------------
    .shared .align 8 .b32 sdata[1024];

    // -------------------------------------------------
    // Registers
    // -------------------------------------------------
    .reg .f16  %pred_h, %targ_h;
    .reg .f32  %pred_f, %targ_f, %prod_f, %diff_f, %relu_f;
    .reg .f32  %sum_f, %tmp_f;
    .reg .u64 %addr_pred, %addr_targ;
    .reg .u32 %i, %stride, %idx;

    // Initialize sum accumulator
    mov.f32 %sum_f, 0.0;

    // Compute global thread id and stride
    mul.lo.u32 %idx, %tid, %bdim;          // idx = tid * blockDim.x (unused)
    mul.lo.u32 %stride, %bdim, %gridDim;  // stride = blockDim.x * gridDim.x
    // Since gridDim == 1, stride == blockDim.x
    // Use blockDim.x as the stride
    mov.u32 %stride, %bdim;

    // Loop over elements: i = threadIdx.x; i < N; i += stride
    mov.u32 %i, %tid;
LOOP:
    setp.ge.u32 %p1, %i, %N;
    @%p1 bra DONE_LOOP;

    // Compute addresses: base + i * sizeof(half) (2 bytes)
    cvt.u64.u32 %addr_pred, %i;
    mul.lo.u64 %addr_pred, %addr_pred, 2;
    add.u64 %addr_pred, %addr_pred, %pred;

    cvt.u64.u32 %addr_targ, %i;
    mul.lo.u64 %addr_targ, %addr_targ, 2;
    add.u64 %addr_targ, %addr_targ, %targ;

    // Load half values
    ld.global.f16 %pred_h, [%addr_pred];
    ld.global.f16 %targ_h, [%addr_targ];

    // Convert to fp32
    cvt.f32.f16 %pred_f, %pred_h;
    cvt.f32.f16 %targ_f, %targ_h;

    // prod = pred_f * targ_f
    mul.f32 %prod_f, %pred_f, %targ_f;

    // diff = 1.0f - prod
    sub.f32 %diff_f, 1.0, %prod_f;

    // relu = max(diff, 0.0)
    max.f32 %relu_f, %diff_f, 0.0;

    // sum += relu
    add.f32 %sum_f, %sum_f, %relu_f;

    // i += stride
    add.u32 %i, %i, %stride;
    bra LOOP;
DONE_LOOP:

    // -------------------------------------------------
    // Store per‑thread sum into shared memory
    // -------------------------------------------------
    st.shared.b32 [sdata + %tid*4], %sum_f;

    // -------------------------------------------------
    // Block reduction using binary tree in shared memory
    // -------------------------------------------------
    bar.sync 0;

    // Reduction loop: offset = blockDim/2 .. 1
    .reg .u32 %offset;
    mov.u32 %offset, %bdim;
    shr.u32 %offset, %offset, 1;          // offset = blockDim.x / 2
REDUCTION_LOOP:
    setp.eq.u32 %p2, %offset, 0;
    @%p2 bra END_REDUCTION;

    setp.lt.u32 %p3, %tid, %offset;
    @%p3 {
        // load left and right values
        ld.shared.b32 %tmp_f, [sdata + %tid*4];
        ld.shared.b32 %tmp_f, [sdata + (%tid + %offset)*4];
        add.f32 %tmp_f, %tmp_f, %tmp_f;          // tmp_f = left + right
        st.shared.b32 [sdata + %tid*4], %tmp_f;
    }
    bar.sync 0;
    shr.u32 %offset, %offset, 1;
    bra REDUCTION_LOOP;
END_REDUCTION:

    // -------------------------------------------------
    // Thread 0 writes final mean to output
    // -------------------------------------------------
    setp.ne.u32 %p4, %tid, 0;
    @%p4 bra END_KERNEL;

    // Load block sum (now in sdata[0])
    ld.shared.b32 %tmp_f, [sdata];

    // Convert N to float and divide
    cvt.f32.u32 %tmp_f, %N;
    div.f32 %tmp_f, %tmp_f, %tmp_f;   // placeholder to avoid warning
    // Actually we need  sum / N
    ld.shared.b32 %sum_f, [sdata];
    cvt.f32.u32 %tmp_f, %N;
    div.f32 %sum_f, %sum_f, %tmp_f;   // sum_f = sum / N

    // Convert to half (round to nearest)
    cvt.rn.f16 %pred_h, %sum_f;

    // Store result
    st.global.f16 [%out], %pred_h;

END_KERNEL:
    ret;
}
"""

# -------------------------------------------------------------------------
# Python wrapper that loads and launches the PTX kernel
# -------------------------------------------------------------------------
import torch

class ModelNew:
    def __init__(self):
        # Load PTX module via harness (ptx_load is provided by the environment)
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        assert predictions.is_cuda and targets.is_cuda
        assert predictions.dtype == torch.float16 and targets.dtype == torch.float16
        N = predictions.numel()
        out = torch.empty(1, dtype=torch.float16, device='cuda')

        # Kernel launch configuration: 1 block, 1024 threads (must be <= 1024)
        grid = (1, 1, 1)
        block = (1024, 1, 1)

        # Arguments: raw pointers and size
        args = [
            predictions.data_ptr(),
            targets.data_ptr(),
            out.data_ptr(),
            N
        ]

        # Launch kernel via harness (ptx_launch is provided by the environment)
        ptx_launch(self.module, "hinge_mean_kernel", grid, block, args)

        return out
